let inputData = $items("Mulai")[0].json;
let dbData = $input.all();
let output_text = "";
const shortUrlBase = "https://gkr.my.id/go/";

if (dbData.length > 0 && dbData[0].json && Object.keys(dbData[0].json).length > 0) {
    let row = dbData[0].json;
    output_text = "*Kode BOM: " + (row.kode_bom || inputData.keyword) + "*\n";
    if (row.item_name) output_text += "Nama Barang: " + row.item_name + "\n";
    if (row.dimensi) output_text += "Dimensi: " + row.dimensi + "\n";
    if (row.packing) output_text += "Packing: " + row.packing + "\n";
    if (row.finishing) output_text += "Finishing: " + row.finishing + "\n";
    if (row.buyer) output_text += "Buyer: " + row.buyer + "\n";

    if (row.bom_name) {
        output_text += "\nDefault Kode BOM: " + row.bom_name + "\n";
        output_text += shortUrlBase + encodeURIComponent(row.bom_name.trim());
    } else if (row.kode_bom) {
        output_text += "\n" + shortUrlBase + encodeURIComponent(row.kode_bom.trim());
    }
} else {
    output_text = "Maaf, data ERP untuk kode '" + inputData.keyword + "' tidak ditemukan di dalam sistem.";
}

return [{ json: Object.assign({}, inputData, { output_text: output_text }) }];
